function printSummary(out)
%PRINTSUMMARY Print high-signal simulation and model-comparison diagnostics.

    opts = out.options;
    comparison = out.modelComparison;
    fprintf(['[hop/trap membrane SPT] truth=%s, preset=%s, ' ...
        'Dfree=%.4g um^2/s, %d localizations, %d independent steps.\n'], ...
        opts.diffusionMode, opts.referencePresetResolved, ...
        opts.freeDiffusionUm2PerS, height(out.localizationTable), ...
        height(out.stepTable));
    fprintf(['[model evidence] classification=%s, ' ...
        'DeltaBIC_trap=%.3g, DeltaqBIC_hop=%.3g.\n'], ...
        comparison.classification.label, ...
        comparison.deltaTrapBic, comparison.deltaHopQuasiBic);

    if comparison.trapHmm.estimateAvailable
        fprintf(['[trap HMM] Dslow=%.4g, Dfast=%.4g um^2/s, ' ...
            'slow/fast=%.3g, dwell=[%.4g %.4g] s.\n'], ...
            comparison.trapHmm.diffusionUm2PerS(1), ...
            comparison.trapHmm.diffusionUm2PerS(2), ...
            comparison.trapHmm.diffusionRatioSlowToFast, ...
            comparison.trapHmm.meanDwellTimeS(1), ...
            comparison.trapHmm.meanDwellTimeS(2));
    end
    if comparison.hopMsd.estimateAvailable
        fprintf(['[hop MSD] Dshort=%.4g, Dlong=%.4g um^2/s, ' ...
            'effective compartment=%.4g um, tauConf=%.4g s.\n'], ...
            comparison.hopMsd.shortRangeDiffusionUm2PerS, ...
            comparison.hopMsd.longRangeDiffusionUm2PerS, ...
            comparison.hopMsd.effectiveCompartmentSizeUm, ...
            comparison.hopMsd.confinementTimeS);
    end
    if out.stickyBnp.estimateAvailable
        fprintf(['[sticky BNP] active-state count mode=%d, mean=%.3g; ' ...
            'this diagnoses mobility states, not fence geometry.\n'], ...
            out.stickyBnp.posteriorModeStateCount, ...
            out.stickyBnp.posteriorMeanStateCount);
    else
        fprintf('[sticky BNP] no estimate (%s).\n', out.stickyBnp.status);
    end
end
